def count_prefix_occurrences(s):
    n = len(s)
    if n == 0:
        return []

    pi = [0] * n
    k = 0
    for q in range(1, n):
        while k > 0 and s[k] != s[q]:
            k = pi[k - 1]
        if s[k] == s[q]:
            k += 1
        pi[q] = k

    count = [1] * n
    for i in range(n - 1, 0, -1):
        count[pi[i] - 1] += count[i]

    return count

